begin;
select set_config('scene.qa_owner',gen_random_uuid()::text,true),set_config('scene.qa_session',gen_random_uuid()::text,true),set_config('scene.qa_factor',gen_random_uuid()::text,true);
insert into auth.users(id,email,aud,role) values(current_setting('scene.qa_owner')::uuid,'release-fixture@example.invalid','authenticated','authenticated');
insert into public.scene_members(user_id,email,display_name,role) values(current_setting('scene.qa_owner')::uuid,'release-fixture@example.invalid','Editor fixture','owner');
insert into auth.mfa_factors(id,user_id,friendly_name,factor_type,status,created_at,updated_at,secret) values(current_setting('scene.qa_factor')::uuid,current_setting('scene.qa_owner')::uuid,'Fixture','totp','verified',now(),now(),'fixture');
insert into auth.sessions(id,user_id,created_at,updated_at,aal,factor_id) values(current_setting('scene.qa_session')::uuid,current_setting('scene.qa_owner')::uuid,now(),now(),'aal2',current_setting('scene.qa_factor')::uuid);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('scene.qa_owner'),'session_id',current_setting('scene.qa_session'),'role','authenticated','aal','aal2','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',floor(extract(epoch from now())))))::text,true);
set local role authenticated;
do $$declare r jsonb;d jsonb;saved jsonb;begin
 if not (public.scene_security_state()->>'adminReady')::boolean then raise exception 'Recent owner MFA not recognized';end if;
 r:=jsonb_build_object('id','qa-editor-record','title','Fixture','kind','series','original_year',2026,'release_date',current_date+1,'service_key','netflix','label','Season 2','source_url','https://about.netflix.com/en/news/fixture','verified_on',current_date,'active',true,'tmdb_id',null,'poster_url',null);
 saved:=public.scene_manage_releases('save','release',r,null);
 if saved->>'title'<>'Fixture' then raise exception 'New release not saved';end if;
 perform public.scene_manage_releases('save','release',r||'{"active":false}',(saved->>'updated_at')::timestamptz);
 begin perform public.scene_manage_releases('save','release',r,(saved->>'updated_at')::timestamptz);raise exception 'Stale edit overwrote latest';exception when serialization_failure then null;end;
 begin perform public.scene_manage_releases('save','release',r||'{"id":"qa-editor-bad","source_url":"https://netflix.com.evil.invalid/"}',null);raise exception 'False official source accepted';exception when raise_exception then if sqlerrm='False official source accepted' then raise;end if;end;
 d:=r-'release_date'-'label'||jsonb_build_object('id','qa-editor-departure','last_available_date',current_date+5);
 perform public.scene_manage_releases('save','departure',d,null);
 d:=public.scene_manage_releases('list');
 if not exists(select 1 from jsonb_array_elements(d->'departures') x where x->>'id'='qa-editor-departure') then raise exception 'Departure missing from dashboard';end if;
 if d->'status'?'public_vapid_key' then raise exception 'Unnecessary config exposed';end if;
 begin select to_jsonb(x) into r from scene_private.release_edits x limit 1;raise exception 'Direct audit table read allowed';exception when insufficient_privilege then null;end;
end$$;
reset role;
select set_config('request.jwt.claims',jsonb_set(current_setting('request.jwt.claims')::jsonb,'{amr}',jsonb_build_array(jsonb_build_object('method','totp','timestamp',floor(extract(epoch from now()))-601)))::text,true);
set local role authenticated;
do $$begin begin perform public.scene_manage_releases('list');raise exception 'Stale MFA allowed';exception when insufficient_privilege then null;end;end$$;
reset role;
update public.scene_members set role='member' where user_id=current_setting('scene.qa_owner')::uuid;
select set_config('request.jwt.claims',jsonb_set(current_setting('request.jwt.claims')::jsonb,'{amr}',jsonb_build_array(jsonb_build_object('method','totp','timestamp',floor(extract(epoch from now())))))::text,true);
set local role authenticated;
do $$begin begin perform public.scene_manage_releases('list');raise exception 'Member accessed owner dashboard';exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
select 'PASS: owner MFA, new and edited announcements, expiry records, optimistic concurrency, official-source validation and member denial' as result;
